WITH RECURSIVE f(n, a, b) AS (SELECT 1, 0, 1 UNION ALL SELECT n + 1, b, a + b FROM f WHERE n < 50) SELECT n, a FROM f ORDER BY n DESC LIMIT 5;
WITH RECURSIVE s(x) AS (SELECT 8 UNION ALL SELECT CASE WHEN x % 2 THEN 3 * x + 1 ELSE x / 2 END FROM s WHERE x <> 1) SELECT count(*), max(x), group_concat(x) FROM s;
WITH a(x) AS (VALUES(1),(2),(3)), b(y) AS (SELECT x * x FROM a) SELECT x, y FROM a, b ORDER BY x, y;
